        }
        if ($action === 'import_preview') {
            $requestedMode=post_string('import_mode');$mode=in_array($requestedMode,['feedback','planning','structure'],true)?$requestedMode:'feedback';$uploads=import_uploaded_files();$allRows=[];$files=[];
            $replaceRequested=$mode==='planning'&&post_string('replace_services')==='1';$replaceDomain=['technical'=>true,'outside'=>true];
            foreach($uploads as $sourceIndex=>$upload){$rawFile=read_import_file($upload['tmp_name'],$upload['extension']);$rawRows=$rawFile['rows'];if($replaceRequested){$columnMap=import_column_map($rawRows[0]??[]);if(!isset($columnMap['service_choice_functional'])&&!isset($columnMap['service_choice_technical'])&&!isset($columnMap['outside_catalog']))throw new RuntimeException('„Datei ist maßgeblich“ ist nur für TPL-/PL-Planungsdateien möglich. Die Datei „'.$upload['name'].'“ ist keine.');$replaceDomain['technical']=$replaceDomain['technical']&&isset($columnMap['service_choice_technical']);$replaceDomain['outside']=$replaceDomain['outside']&&isset($columnMap['outside_catalog']);}$prepared=prepare_import_wizard($db,$rawRows,$rawFile['strike']);if($mode!=='planning')foreach($prepared as &$struckRow)if(($struckRow['include']??true)==='remove')$struckRow['include']=false;unset($struckRow);foreach($prepared as &$preparedRow){$preparedRow['source_index']=$sourceIndex;$preparedRow['source_file']=$upload['name'];}unset($preparedRow);if($mode!=='structure')$prepared=match_existing_import_targets($db,$prepared);$providerId=$mode==='feedback'?detect_feedback_provider($db,$upload['name'],$prepared):0;if($providerId)foreach($prepared as &$preparedRow)$preparedRow['provider_id']=$providerId;unset($preparedRow);$files[]=['index'=>$sourceIndex,'name'=>$upload['name'],'provider_id'=>$providerId];array_push($allRows,...$prepared);}
            $_SESSION['import_wizard']=['token'=>bin2hex(random_bytes(16)),'kind'=>'data','stage'=>'review','mode'=>$mode,'replace'=>$replaceRequested,'replace_domain'=>$replaceDomain,'files'=>$files,'rows'=>$allRows];
