        $includeProviderData=(string)($_GET['include_provider_data']??'')==='1';
        if($type==='tpl-projects')download_tpl_template_archive($db,$includeProviderData);
        if($type==='tpl-project')download_tpl_template($db,(int)($_GET['project_id']??0),$includeProviderData);
