        if($type==='phase-rv')download_provider_template_archive($db,['RV'],'Regionalverbaende-Unterstuetzungsabfrage');
        if(in_array($type,['catalog-rv','catalog-fi','catalog-dsv'],true))download_catalog_maintenance($db,strtoupper(substr($type,8)));
        if($type==='providers')download_provider_template_archive($db,['FI','DSV','RV'],'Rollout-Unterstuetzung-Leistungserbringer');
        if($type==='provider')download_provider_template($db,(int)($_GET['provider_id']??0));
        download_tpl_template($db,0,$includeProviderData);
    } catch (Throwable $error) {
        flash('danger','Die Excel-Vorlage konnte nicht erstellt werden: '.$error->getMessage());
        redirect('?page=import');
    }
}
