function render_footer(): void { ?></main><script src="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/js/bootstrap.bundle.min.js"></script><script>document.querySelectorAll('[data-confirm]').forEach(el=>el.addEventListener('click',e=>{if(!confirm(el.dataset.confirm))e.preventDefault()}));document.querySelectorAll('.modal').forEach(modal=>modal.addEventListener('shown.bs.modal',()=>modal.querySelector('[data-modal-autofocus]')?.focus()));document.querySelectorAll('[data-cumulative-classes]').forEach(group=>{const boxes=Array.from(group.querySelectorAll('input[type="checkbox"]'));const render=(changed=null)=>{boxes.forEach(box=>{box.disabled=false;box.closest('label')?.classList.remove('cumulative-class-inherited');box.removeAttribute('aria-readonly')});let base=-1;if(changed){const changedIndex=boxes.indexOf(changed);if(changed.checked)base=changedIndex;else boxes.slice(changedIndex+1).forEach(box=>box.checked=false)}if(base<0)base=boxes.findIndex(box=>box.checked);if(base<0)return;boxes.forEach((box,index)=>{if(index>base){box.checked=true;box.disabled=true;box.setAttribute('aria-readonly','true');box.closest('label')?.classList.add('cumulative-class-inherited')}})};render();boxes.forEach(box=>box.addEventListener('change',()=>render(box)))});</script></body></html><?php }

function render_dashboard(PDO $db): void {
    $q=trim((string)($_GET['q']??'')); $params=[]; $where='';
    if($q!==''){ $where='WHERE p.name LIKE ? OR p.project_lead LIKE ? OR p.rollout_lead LIKE ? OR EXISTS(SELECT 1 FROM rollout_objects r2 WHERE r2.project_id=p.id AND r2.name LIKE ?)'; $params=array_fill(0,4,'%'.$q.'%'); }
    $stmt=$db->prepare("SELECT p.*,COUNT(r.id) object_count,MIN(r.start_date) first_start,MAX(r.end_date) last_end FROM projects p LEFT JOIN rollout_objects r ON r.project_id=p.id $where GROUP BY p.id ORDER BY p.name"); $stmt->execute($params); $projects=$stmt->fetchAll();
    $stats=['Projekte'=>(int)$db->query('SELECT COUNT(*) FROM projects')->fetchColumn(),'Rolloutobjekte'=>(int)$db->query('SELECT COUNT(*) FROM rollout_objects')->fetchColumn(),'Unterstützungsleistungen'=>(int)$db->query('SELECT COUNT(*) FROM support_services WHERE active=1')->fetchColumn()]; ?>
