se DSV</label><select class="form-select" name="dsv_class"><option value="">– nicht festgelegt –</option><?php foreach($dsvLevels as $level):?><option value="<?=e($level['class_code'])?>" <?=($object['dsv_class_code']??'')===$level['class_code']?'selected':''?>><?=e($level['class_label'])?></option><?php endforeach;?></select></div><div class="col-12"><div class="form-text">Klasse 0 bedeutet: Für dieses Rolloutobjekt ist beim jeweiligen Verbundpartner keine Unterstützungsleistung erforderlich.</div></div><div class="col-12"><label class="form-label">Anmerkungen</label><textarea class="form-control" rows="4" name="notes"><?=e($object['notes'])?></textarea></div><div class="col-12 d-flex gap-2"><button class="btn btn-primary">Speichern und Matrix öffnen</button><a class="btn btn-outline-secondary" href="?page=project&id=<?=$projectId?>">Abbrechen</a></div></div></form><?php if($id): ?><form method="post" class="mt-3"><?=csrf_field()?><input type="hidden" name="action" value="delete_object"><input type="hidden" name="id" value="<?=$id?>"><input type="hidden" name="project_id" value="<?=$projectId?>"><button class="btn btn-link text-danger px-0" data-confirm="Rolloutobjekt und Matrix wirklich löschen?">Rolloutobjekt löschen</button></form><?php endif; ?><?php }

function render_matrix(PDO $db,int $projectId,int $legacyObjectId=0): void {
    if(!$projectId&&$legacyObjectId){$stmt=$db->prepare('SELECT project_id FROM rollout_objects WHERE id=?');$stmt->execute([$legacyObjectId]);$projectId=(int)$stmt->fetchColumn();}
    $stmt=$db->prepare('SELECT * FROM projects WHERE id=?');$stmt->execute([$projectId]);$project=$stmt->fetch();
    if(!$project){echo '<div class="alert alert-danger">Projekt nicht gefunden.</div>';return;}
    $stmt=$db->prepare('SELECT * FROM rollout_objects WHERE project_id=? ORDER BY start_date,name');$stmt->execute([$projectId]);$objects=enrich_rollout_objects($db,$stmt->fetchAll());
    $providers=$db->query("SELECT * FROM providers WHERE active=1 ORDER BY CASE type WHEN 'FI' THEN 1 WHEN 'DSV' THEN 2 ELSE 3 END,sort_order,name")->fetchAll();
    $stmt=$db->prepare('SELECT * FROM project_provider_contacts WHERE project_id=?');$stmt->execute([$projectId]);$projectContacts=[];foreach($stmt as $contact)$projectContacts[$contact['provider_id']]=$contact;

    $allStandardProjectServices=enrich_support_services($db,$db->query("SELECT * FROM support_services WHERE active=1 AND is_standard=1 ORDER BY name COLLATE NOCASE")->fetchAll());
    $projectClassScope=project_rollout_class_scope($db,$projectId);
    $projectFunctionalMax=$projectClassScope['functional']?$projectClassScope['functional'][count($projectClassScope['functional'])-1]:null;$projectTechnicalMax=$projectClassScope['technical']?$projectClassScope['technical'][count($projectClassScope['technical'])-1]:null;$projectDsvMax=$projectClassScope['dsv']?$projectClassScope['dsv'][count($projectClassScope['dsv'])-1]:null;$dsvLevels=provider_class_levels($db,'DSV');$dsvLabels=array_column($dsvLevels,'class_label','class_code');
    $projectClassObject=['functional_class'=>$projectFunctionalMax,'technical_class'=>$projectTechnicalMax,'dsv_class_code'=>$projectDsvMax];
    $standardProjectGroups=service_selection_groups($allStandardProjectServices,$projectClassScope['functional'],$projectClassScope['technical'],$projectClassScope['dsv']);
    $selectableStandardIds=service_selection_group_ids($standardProjectGroups);$selectableStandardIdMap=array_fill_keys($selectableStandardIds,true);
    $standardProjectServices=array_values(array_filter($allStandardProjectServices,fn($service)=>isset($selectableStandardIdMap[(int)$service['id']])));
    $stmt=$db->prepare('SELECT ps.support_service_id FROM project_services ps JOIN support_services s ON s.id=ps.support_service_id WHERE ps.project_id=? AND s.is_standard=1');$stmt->execute([$projectId]);$selectedProjectServiceIds=array_map('intval',array_column($stmt->fetchAll(),'support_service_id'));
    $stmt=$db->prepare("SELECT s.* FROM support_services s JOIN project_services ps ON ps.support_service_id=s.id WHERE s.active=1 AND ps.project_id=? ORDER BY s.name COLLATE NOCASE");$stmt->execute([$projectId]);$projectServices=array_values(array_filter(enrich_support_services($db,$stmt->fetchAll()),fn($service)=>!$service['is_standard']||isset($selectableStandardIdMap[(int)$service['id']])));
    $projectMandatory=mandatory_project_pairs($db,$projectId);
    $stmt=$db->prepare('SELECT * FROM project_support_matrix WHERE project_id=?');$stmt->execute([$projectId]);$projectMatrix=[];foreach($stmt as $cell)$projectMatrix[$cell['support_service_id']][$cell['provider_id']]=$cell;
    $stmt=$db->prepare('SELECT support_service_id,rollout_object_id FROM project_service_rollout_objects WHERE project_id=?');$stmt->execute([$projectId]);$serviceRolloutUsage=[];foreach($stmt->fetchAll() as $mapping)$serviceRolloutUsage[(int)$mapping['support_service_id']][(int)$mapping['rollout_object_id']]=true; ?>
<div class="project-matrix-page"><div class="d-flex flex-wrap justify-content-between align-items-start gap-3 mb-4"><div><a class="small text-secondary text-decoration-none" href="?page=project&id=<?=$projectId?>">← Projekt</a><h1 class="page-title h2 mt-2 mb-1"><?=e($project['name'])?></h1><div class="text-secondary">Projektleistungen auswählen, ihre Nutzung je Rolloutobjekt festlegen und Rückmeldungen zusammenführen</div></div><a class="btn btn-outline-secondary" href="?page=project&id=<?=$projectId?>">Projekt bearbeiten</a></div>
<div class="alert alert-light border small matrix-info">Unterstützungsleistungen werden dem Projekt zugeordnet und anschließend je Rolloutobjekt genutzt. Die Klassen hängen ausschließlich an den Rolloutobjekten: Bankfachlich A–D, FI 1–3 und DSV nach dem unter „Leistungserbringer“ gepflegten Schema.</div>
<div class="class-color-legend mb-3" aria-label="Farblegende der Leistungsklassen"><span class="small fw-semibold text-muted me-1">Bankfachlicher Rollout</span><?php foreach(['A','B','C','D'] as $class):?><span class="badge service-class-badge class-tone-functional-<?=strtolower($class)?>"><?=$class?></span><?php endforeach;?><span class="small fw-semibold text-muted ms-2 me-1">FI</span><?php foreach(['1','2','3'] as $class):?><span class="badge service-class-badge class-tone-technical-<?=$class?>"><?=$class?></span><?php endforeach;?><span class="small fw-semibold text-muted ms-2 me-1">DSV</span><?php foreach($dsvLevels as $index=>$level):?><span class="badge service-class-badge class-tone-technical-<?=min(3,$index+1)?>"><?=e($level['class_label'])?></span><?php endforeach;?><span class="small text-muted ms-2">blass = niedrigere Klasse · kräftig = höhere Klasse</span></div>
<div class="delivery-legend mb-3"><span class="delivery-key delivery-self">Selbst</span><span class="delivery-key delivery-other">Anderer RV</span><span class="delivery-key delivery-external">Externer DL</span><span class="delivery-key delivery-none">Keine Bereitstellung</span><span class="delivery-key delivery-open">Noch offen</span></div>
<form method="post"><?=csrf_field()?><input type="hidden" name="action" value="save_matrix"><input type="hidden" name="project_id" value="<?=$projectId?>">
<div class="card p-3 p-lg-4 mb-4 matrix-full-width"><h2 class="h5 mb-1">Standardleistungen für dieses Projekt auswählen</h2><p class="small text-secondary mb-2">Die Auswahl wird aus den Klassen der einzelnen Rolloutobjekte abgeleitet.</p><p class="small text-secondary mb-4">Die Klassen gelten kumulativ. Mehrfach klassifizierte Leistungen erscheinen in mehreren passenden Bereichen; die Auswahl wird automatisch synchronisiert.</p>
<?php if($standardProjectServices):$selectionAreas=['functional'=>['title'=>'Bankfachlicher Rollout','classes'=>['A','B','C','D'],'labels'=>[]],'technical'=>['title'=>'FI','classes'=>['1','2','3'],'labels'=>[]],'dsv'=>['title'=>'DSV','classes'=>array_column($dsvLevels,'class_code'),'labels'=>$dsvLabels]];foreach($selectionAreas as $dimension=>$area):$areaCount=array_sum(array_map('count',$standardProjectGroups[$dimension]));if(!$areaCount)continue;?>
<section class="service-selection-area <?=$dimension==='technical'?'service-selection-area-technical':''?>"><div class="d-flex flex-wrap align-items-baseline gap-2 mb-3"><h3 class="h6 mb-0"><?=e($area['title'])?></h3><span class="small text-secondary"><?=$areaCount?> <?=$areaCount===1?'Leistung':'Leistungen'?></span></div>
<?php foreach($area['classes'] as $class):$classServices=$standardProjectGroups[$dimension][$class]??[];if(!$classServices)continue;$displayClass=$area['labels'][$class]??$class;$tone=$dimension==='functional'?'functional-'.strtolower($class):'technical-'.min(3,max(1,(int)preg_replace('/\D+/','',$class)));?><div class="service-selection-class mb-4"><div class="service-selection-class-header"><span class="catalog-group-class class-tone-<?=$tone?>"><?=e($displayClass)?></span><span class="fw-semibold">Klasse <?=e($displayClass)?></span><span class="small text-secondary"><?=count($classServices)?> <?=count($classServices)===1?'Leistung':'Leistungen'?></span></div><div class="row row-cols-1 row-cols-md-2 row-cols-xl-3 row-cols-xxl-4 g-2 mt-1">
<?php foreach($classServices as $service):?><div class="col"><label class="form-check service-option border rounded p-2 ps-5 h-100"><input class="form-check-input" type="checkbox" name="project_standard_service[]" value="<?=$service['id']?>" data-service-selection="<?=$service['id']?>" <?=in_array((int)$service['id'],$selectedProjectServiceIds,true)?'checked':''?>><span class="fw-semibold"><?=e($service['name'])?></span><span class="service-class-badges mt-1"><?=service_class_badges($service)?></span><?php if($service['description']):?><span class="d-block small text-secondary mt-1"><?=e($service['description'])?></span><?php endif;?></label></div><?php endforeach;?></div></div><?php endforeach;?></section><?php endforeach;?>
<?php else:?><div class="alert alert-light border small mb-0"><?php if(!$projectFunctionalMax&&!$projectTechnicalMax&&!$projectDsvMax):?>Für dieses Projekt ist noch keine Rolloutklasse über seine Rolloutobjekte festgelegt. Sobald mindestens ein Rolloutobjekt klassifiziert ist, erscheinen hier die kumulativ passenden Unterstützungsleistungen.<?php elseif(!$allStandardProjectServices):?>Im Standardkatalog sind noch keine Standardleistungen angelegt.<?php else:?>Für die ermittelten Rolloutklassen sind im Standardkatalog keine passenden Unterstützungsleistungen hinterlegt.<?php endif;?></div><?php endif;?></div>
<div class="card p-3 mb-4 matrix-full-width"><h2 class="h5 mb-1">Nutzung der Projektleistungen je Rolloutobjekt</h2><p class="small text-secondary mb-3">Alle Leistungen sind dem Projekt zugeordnet. Hier wird lediglich angehakt, bei welchen Rolloutobjekten die jeweilige Projektleistung genutzt wird.</p><?php if(!$objects):?><div class="alert alert-light border small mb-0">Noch keine Rolloutobjekte vorhanden.</div><?php elseif(!$projectServices):?><div class="alert alert-light border small mb-0">Bitte zuerst oben mindestens eine Standardleistung auswählen und speichern oder eine zusätzliche Projektleistung anlegen.</div><?php else:?><div class="table-responsive"><table class="table table-sm table-bordered align-middle mb-0"><thead><tr><th>Projektleistung</th><?php foreach($objects as $object):?><th class="text-center"><span class="d-block"><?=e($object['name'])?></span><span class="small fw-normal text-secondary"><?=e(class_label($object))?></span></th><?php endforeach;?></tr></thead><tbody><?php foreach($projectServices as $service):?><tr><th><span class="fw-semibold"><?=e($service['name'])?></span><span class="service-class-badges mt-1"><?=service_class_badges($service)?></span></th><?php foreach($objects as $object):$applicable=service_applies_to_rollout_object($service,$object);?><td class="text-center"><?php if($applicable&&!empty($service['always_included'])):?><input class="form-check-input" type="checkbox" checked disabled title="Immer enthalten – nicht abwählbar" aria-label="<?=e($service['name'].' für '.$object['name'].' (immer enthalten)')?>"><?php elseif($applicable):?><input class="form-check-input" type="checkbox" name="service_rollout[<?=$service['id']?>][<?=$object['id']?>]" value="1" <?=isset($serviceRolloutUsage[$service['id']][$object['id']])?'checked':''?> aria-label="<?=e($service['name'].' für '.$object['name'])?>"><?php else:?><span class="text-secondary" title="Für die Klassen dieses Rolloutobjekts nicht passend">–</span><?php endif;?></td><?php endforeach;?></tr><?php endforeach;?></tbody></table></div><?php endif;?></div>
<div class="card p-3 mb-4 matrix-full-width"><h2 class="h5 mb-1">Ansprechpartner der Leistungserbringer</h2><p class="small text-secondary">Je Projekt wird für FI, DSV und jeden Regionalverband genau ein Ansprechpartner hinterlegt.</p><div class="table-responsive"><table class="table table-sm align-middle mb-0"><thead><tr><th>Leistungserbringer</th><th>Ansprechpartner</th><th>Telefonnummer</th></tr></thead><tbody><?php foreach($providers as $provider):$contact=$projectContacts[$provider['id']]??null;?><tr><td class="fw-semibold"><?=e($provider['name'])?></td><td><input class="form-control form-control-sm" name="project_contact[<?=$provider['id']?>][contact_name]" value="<?=e($contact['contact_name']??'')?>" placeholder="Name"></td><td><input type="tel" class="form-control form-control-sm" name="project_contact[<?=$provider['id']?>][contact_phone]" value="<?=e($contact['contact_phone']??'')?>" placeholder="Telefonnummer"></td></tr><?php endforeach;?></tbody></table></div></div>
<div class="card matrix-wrap"><table class="table table-bordered matrix-table align-middle mb-0"><thead><tr><th>Ebene / Unterstützungsleistung</th><?php foreach($providers as $provider): ?><th class="text-center"><?=e($provider['name'])?></th><?php endforeach; ?></tr></thead><tbody>
<tr class="matrix-section"><th colspan="<?=count($providers)+1?>"><span class="badge text-bg-dark me-2">Projektleistungen</span><?=e($project['name'])?> <a class="btn btn-sm btn-outline-dark ms-3" href="?page=custom-service&project_id=<?=$projectId?>">+ Zusätzliche Projektleistung</a></th></tr>
<?php if(!$projectServices): ?><tr><td colspan="<?=count($providers)+1?>" class="text-secondary py-3">Noch keine projektweite Unterstützungsleistung zugeordnet.</td></tr><?php else: foreach($projectServices as $service)render_matrix_service_row($service,$providers,$projectMatrix,'project_cell',$projectMandatory,'project-'.$service['id'],$projectId,0,$projectClassObject);endif; ?>
</tbody></table></div><div class="mt-3 d-flex gap-2"><button class="btn btn-primary">Gesamte Projektmatrix speichern</button><a class="btn btn-outline-secondary" href="?page=catalog">Standardkatalog öffnen</a></div></form></div><script>(()=>{const update=select=>{const cell=select.closest('[data-delivery-cell]');if(!cell)return;cell.dataset.deliveryState=select.value||'open';cell.querySelector('[data-delivery-other]').hidden=select.value!=='other_rv';cell.querySelector('[data-delivery-external]').hidden=select.value!=='external';};document.querySelectorAll('[data-delivery-mode]').forEach(select=>{update(select);select.addEventListener('change',()=>update(select));});document.querySelectorAll('[data-service-selection]').forEach(box=>box.addEventListener('change',()=>{document.querySelectorAll('[data-service-selection="'+box.dataset.serviceSelection+'"]').forEach(peer=>peer.checked=box.checked);}));})();</script><?php }

function render_matrix_service_row(array $service,array $providers,array $matrix,string $prefix,array $mandatoryPairs,string $idPrefix,int $projectId,int $objectId,?array $object): void {
