<?php if(!$changes):?><div class="alert alert-info">Die Datei führt zu keiner inhaltlichen Änderung gegenüber dem aktuellen Datenbankstand.</div><?php else:?><div class="card matrix-wrap"><table class="table table-bordered align-middle mb-0"><thead><tr><th>Art</th><th>Bereich</th><th>Datensatz</th><th>Feld</th><th>Bisher</th><th>Nach Import</th></tr></thead><tbody><?php foreach($changes as $change):?><tr><td><span class="badge text-bg-<?=$colors[$change['type']]?>"><?=e($labels[$change['type']])?></span></td><td><?=e($change['category'])?></td><td class="fw-semibold"><?=e($change['subject'])?></td><td><?=e($change['field'])?></td><td class="text-break"><?=e($change['old']!==''?$change['old']:'(leer)')?></td><td class="text-break"><?=e($change['new']!==''?$change['new']:'(leer)')?></td></tr><?php endforeach;?></tbody></table></div><?php endif;?>
<div class="mt-3 d-flex flex-wrap gap-2"><form method="post"><?=csrf_field()?><input type="hidden" name="action" value="import_apply"><input type="hidden" name="wizard_token" value="<?=e($wizard['token'])?>"><button class="btn btn-danger" <?=$changes?'':'disabled'?>>Änderungen jetzt verbindlich importieren</button></form><form method="post"><?=csrf_field()?><input type="hidden" name="action" value="import_back"><input type="hidden" name="wizard_token" value="<?=e($wizard['token'])?>"><button class="btn btn-outline-primary"><?=($wizard['kind']??'')==='catalog'?'Andere Datei auswählen':'Zurück zur Zuordnung'?></button></form><form method="post"><?=csrf_field()?><input type="hidden" name="action" value="import_cancel"><button class="btn btn-outline-secondary">Import vollständig verwerfen</button></form></div></div><?php
