<div class="mt-3 d-flex gap-2"><button class="btn btn-primary">Änderungen gegenüber der Datenbank anzeigen</button><button class="btn btn-outline-secondary" type="submit" form="import-cancel-form">Import verwerfen</button></div></form><form method="post" id="import-cancel-form"><?=csrf_field()?><input type="hidden" name="action" value="import_cancel"></form></div><script>(()=>{const form=document.getElementById('import-review-form');const filterObjects=row=>{const project=row.querySelector('[data-field="project_id"]'),object=row.querySelector('[data-field="object_id"]');if(!project||!object)return;Array.from(object.options).forEach(option=>{if(option.dataset.projectId)option.hidden=option.dataset.projectId!==project.value});if(object.selectedOptions[0]?.hidden)object.value=''};form.querySelectorAll('[data-import-row]').forEach(row=>{filterObjects(row);row.querySelector('[data-field="project_id"]')?.addEventListener('change',()=>filterObjects(row))});form.addEventListener('submit',function(){const rows=[];this.querySelectorAll('[data-import-row]').forEach(row=>{const values={};row.querySelectorAll('[data-field]').forEach(field=>values[field.dataset.field]=field.type==='checkbox'?(field.checked?'1':''):field.value);rows.push(values)});const files={};this.querySelectorAll('[data-file-provider]').forEach(field=>files[field.dataset.fileProvider]=field.value);document.getElementById('review-payload').value=JSON.stringify({rows,files})})})();</script>
<script>(()=>{
const form=document.getElementById('import-review-form');if(!form)return;
const state=JSON.parse(document.getElementById('import-db-state').textContent);
const mode=form.dataset.mode;
const key=v=>(v||'').toLowerCase().replace(/[^a-z0-9äöüß]/g,'');
const esc=v=>String(v).replace(/[&<>"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[c]));
const val=(row,name)=>{const f=row.querySelector('[data-field="'+name+'"]');if(!f)return '';return f.type==='checkbox'?(f.checked?'1':''):f.value.trim()};
const optText=(row,name)=>{const f=row.querySelector('[data-field="'+name+'"]');return f&&f.selectedOptions[0]?f.selectedOptions[0].textContent.replace(/ · .*$/,'').trim():''};
const shown=v=>v===''?'<em class="text-secondary">leer</em>':esc(v);
const field=(label,oldV,newV)=>oldV===newV
 ?'<div class="text-secondary">'+label+': '+shown(newV)+' <span>(unverändert)</span></div>'
 :'<div class="bg-warning-subtle rounded px-1">'+label+': <span class="text-decoration-line-through text-secondary">'+shown(oldV)+'</span> → <strong>'+shown(newV)+'</strong></div>';
const compare=row=>{
 const out=[];let changed=false;const flag=(html,isChange)=>{out.push(html);if(isChange)changed=true};
 const service=val(row,'service'),choice=val(row,'service_id'),scope=val(row,'scope');
 let objectId=val(row,'object_id');
 if(val(row,'include')==='remove'){
  const had=objectId&&/^\d+$/.test(choice)&&!!state.usage[objectId+':'+choice];
  if(!/^\d+$/.test(choice))flag('<div class="text-secondary">Leistung „'+esc(service)+'“ ist keine bekannte Leistung – nichts zu entfernen</div>',false);
  else if(state.mandatory[choice])flag('<div class="text-secondary">Streichung nicht möglich: „'+esc(optText(row,'service_id'))+'“ ist als „Immer enthalten“ markiert und bleibt erhalten</div>',false);
  else if(!had)flag('<div class="text-secondary">„'+esc(optText(row,'service_id'))+'“ ist am Objekt nicht eingetragen – nichts zu entfernen</div>',false);
  else flag('<div class="bg-danger-subtle rounded px-1">Leistung „'+esc(optText(row,'service_id'))+'“: <strong>wird am Objekt entfernt</strong></div>',true);
  row.querySelector('[data-compare]').innerHTML=out.join('');row.dataset.changed=changed?'1':'';return;
 }
 if(!objectId&&mode==='structure')objectId=state.byName[key(val(row,'project'))+'|'+key(val(row,'object'))]||'';
 const old=objectId?state.objects[objectId]:null;
 if(scope==='Rolloutobjekt'&&val(row,'object')!==''&&!old)flag('<div class="text-success fw-semibold">Rolloutobjekt wird neu angelegt</div>',true);
 const providerType=()=>{const fs=form.querySelector('[data-file-provider="'+row.dataset.sourceIndex+'"]');return state.providerTypes[(fs&&fs.value)||val(row,'provider_id')]||''};
 if(mode==='feedback'&&service===''){
  if(old){
   const type=providerType();
   if(type==='FI'||type==='DSV'){const was=old[type]||'',now=val(row,'provider_class');const lbl=c=>c===''?'':((state.classLabels[type]||{})[c]||c);flag(field('Rolloutklasse '+type,lbl(was),lbl(now)),now!==''&&was!==now)}
   const fs=val(row,'start'),fe=val(row,'end');
   if((fs&&fs!==old.s)||(fe&&fe!==old.e))out.push('<div class="text-secondary">Zeitraum laut Datei '+esc(fs||'–')+' – '+esc(fe||'–')+' weicht ab ('+esc(old.s||'–')+' – '+esc(old.e||'–')+'). Er wird hier nicht übernommen; Zeiträume ändert nur der TPL-/PL-Import.</div>');
  }
 }else if(service===''){
  if(old){
   const start=val(row,'start'),end=val(row,'end'),cls=val(row,'functional'),note=val(row,'note');
   if(start!==''||end!==''||cls!==''||note!==''){
    if(start!=='')flag(field('Beginn',old.s,start),old.s!==start);
    if(end!=='')flag(field('Ende',old.e,end),old.e!==end);
    if(cls!=='')flag(field('Klasse Bankfachlich',old.f,cls),old.f!==cls);
    if(note!=='')flag(field('Bemerkung',old.n,note),old.n!==note);
   }
  }
 }else if(choice===''){flag('<div class="text-danger fw-semibold">Zuordnung der Leistung fehlt</div>',false)}
 else if(choice==='skip_service'){out.push('<div class="text-secondary">Leistung „'+esc(service)+'“ wird ignoriert</div>')}
 else if(choice==='new_custom'&&row.dataset.newLeader){flag('<div class="text-success">Neue Leistung „'+esc(service)+'“ wird nur einmal angelegt (wie bei „'+esc(row.dataset.newLeader)+'“) und hier zugeordnet</div>',true)}
 else if(choice==='new_custom'){const t=val(row,'provider_targets');const parts=[];if(t.includes('RV'))parts.push('RV ab Klasse '+val(row,'new_class'));if(t.includes('FI'))parts.push('FI ab Klasse '+val(row,'new_fi_class'));if(t.includes('DSV'))parts.push('DSV ab '+optText(row,'new_dsv_class'));flag('<div class="text-success fw-semibold">Neue '+(val(row,'create_standard')?'Standardleistung (zentraler Katalog)':'Projektleistung')+': „'+esc(service)+'“</div><div class="text-secondary">'+(parts.length?esc(parts.join(' · ')):'<span class="text-danger">Zuständigkeit wählen</span>')+'</div>',true)}
 else if(choice==='new_catalog_suggestion'){flag('<div class="text-success fw-semibold">Katalogvorschlag: „'+esc(service)+'“</div>',true)}
 else if(mode==='feedback'){
  const fileSelect=form.querySelector('[data-file-provider="'+row.dataset.sourceIndex+'"]');const provider=(fileSelect&&fileSelect.value)||val(row,'provider_id');const project=val(row,'project_id');
  const m=state.matrix[project+':'+choice+':'+provider];
  const nv={o:(['FI','DSV'].includes(state.providerTypes[provider])||row.querySelector('[data-field="offered"]')?.checked)?'Ja':'Nein',m:optText(row,'delivery_mode').replace('– nicht angegeben –',''),pa:val(row,'delivery_partner'),s:val(row,'schedule'),n:val(row,'note')};
  out.push('<div class="fw-semibold">'+esc(optText(row,'service_id'))+'</div>');
  if(!m)flag('<div class="text-success">Neue Rückmeldung: Geplant '+nv.o+(nv.m?' · '+esc(nv.m):'')+(nv.s?' · '+esc(nv.s):'')+'</div>',true);
  else{flag(field('Geplant',m.o,nv.o),m.o!==nv.o);if(nv.m!==''||m.m!=='')flag(field('Bereitstellung',m.m,nv.m),m.m!==nv.m);if(nv.pa!==''||m.pa!=='')flag(field('Partner',m.pa,nv.pa),m.pa!==nv.pa);if(nv.s!==''||m.s!=='')flag(field('Termin',m.s,nv.s),m.s!==nv.s);if(nv.n!==''||m.n!=='')flag(field('Bemerkung',m.n,nv.n),m.n!==nv.n)}
 }else if(objectId){
  const had=!!state.usage[objectId+':'+choice];
  flag('<div class="'+(had?'text-secondary':'bg-warning-subtle rounded px-1')+'">Leistung „'+esc(optText(row,'service_id'))+'“: '+(had?'bereits am Objekt vorgesehen (unverändert)':'<strong>neu am Objekt vorgesehen</strong>')+'</div>',!had);
 }
 if(!out.length)out.push('<span class="text-secondary">keine Datenänderung erkennbar</span>');
 const cell=row.querySelector('[data-compare]');cell.innerHTML=out.join('');row.dataset.changed=changed?'1':'';
};
const refreshRow=row=>{
 compare(row);
 const off=val(row,'include')==='';row.classList.toggle('table-secondary',off);row.classList.toggle('opacity-50',off);row.classList.toggle('table-danger',val(row,'include')==='remove');
 row.classList.toggle('import-master-row',val(row,'service')===''&&!row.querySelector('[data-inherit]'));
};
const syncPanel=row=>{
 const panel=row.querySelector('[data-new-panel]');if(!panel)return;
 panel.hidden=val(row,'service_id')!=='new_custom';
 const targets=[...panel.querySelectorAll('[data-target]')].filter(c=>c.checked).map(c=>c.dataset.target);
 panel.querySelector('[data-field="provider_targets"]').value=targets.join(',');
 panel.querySelector('[data-new-rv]').hidden=!targets.includes('RV');panel.querySelector('[data-new-fi]').hidden=!targets.includes('FI');panel.querySelector('[data-new-dsv]').hidden=!targets.includes('DSV');
};
form.querySelectorAll('[data-pclass-select]').forEach(sel=>sel.addEventListener('change',()=>{sel.dataset.touched='1'}));
const rowProviderType=row=>{if(mode!=='feedback')return '';const fs=form.querySelector('[data-file-provider="'+row.dataset.sourceIndex+'"]');return state.providerTypes[(fs&&fs.value)||val(row,'provider_id')]||''};
const filterServiceOptions=()=>{
 rows.forEach(row=>{
  const sel=row.querySelector('[data-field="service_id"]');if(!sel)return;const type=rowProviderType(row);
  sel.querySelectorAll('option[data-targets]').forEach(o=>{
   const fits=!type||o.dataset.targets.split(',').includes(type);o.hidden=!fits&&!o.selected;
   const cls=type?o.dataset['class'+type.charAt(0)+type.slice(1).toLowerCase()]:'';
   o.textContent=o.dataset.name+' · '+o.dataset.context+(type&&cls?' · '+type+' ab Klasse '+cls:'')+(!fits&&o.selected?' · nicht für '+type+' vorgesehen':'');
  });
  if(type&&row.dataset.optType!==type){sel.querySelectorAll('optgroup').forEach(g=>{const field='class'+type.charAt(0)+type.slice(1).toLowerCase();[...g.querySelectorAll('option')].sort((a,b)=>(a.dataset[field]||'~').localeCompare(b.dataset[field]||'~','de',{numeric:true})||a.dataset.name.localeCompare(b.dataset.name,'de')).forEach(o=>g.appendChild(o))});row.dataset.optType=type}
 });
};
const syncNewGroups=()=>{
 const leaders={};
 rows.forEach(row=>{
  const panel=row.querySelector('[data-new-panel]');const note=row.querySelector('[data-new-follower]');
  delete row.dataset.newLeader;if(note)note.hidden=true;
  if(!panel||val(row,'service_id')!=='new_custom'||val(row,'include')==='')return;
  const k=key(val(row,'service'));if(!leaders[k]){leaders[k]=row;return}
  const lead=leaders[k];
  panel.querySelectorAll('[data-target]').forEach(c=>{c.checked=!!lead.querySelector('[data-target="'+c.dataset.target+'"]')?.checked});
  ['create_standard'].forEach(n=>{const a=lead.querySelector('[data-field="'+n+'"]'),b=row.querySelector('[data-field="'+n+'"]');if(a&&b)b.checked=a.checked});
  ['new_class','new_fi_class','new_dsv_class'].forEach(n=>{const a=lead.querySelector('[data-field="'+n+'"]'),b=row.querySelector('[data-field="'+n+'"]');if(a&&b)b.value=a.value});
  syncPanel(row);panel.hidden=true;row.dataset.newLeader=val(lead,'object')||'oben';
  if(note){note.hidden=false;note.textContent='Wird nur einmal angelegt – Festlegung wie bei „'+row.dataset.newLeader+'“ (erste Zeile mit diesem Namen).'}
 });
};
const updateFeedback=()=>{
 if(mode!=='feedback')return;
 const typeOf=row=>{const fs=form.querySelector('[data-file-provider="'+row.dataset.sourceIndex+'"]');return state.providerTypes[(fs&&fs.value)||val(row,'provider_id')]||''};
 const masters={};let anyRv=false;
 rows.forEach(row=>{
  const type=typeOf(row);if(type==='RV')anyRv=true;
  const id=val(row,'object_id');const old=id?state.objects[id]:null;
  row.querySelectorAll('[data-dbdate]').forEach(el=>el.textContent=old?(old[el.dataset.dbdate==='start'?'s':'e']||'–'):'–');
  const sel=row.querySelector('[data-pclass-select]');
  if(sel){sel.querySelectorAll('optgroup').forEach(g=>{g.hidden=g.dataset.type!==type;g.disabled=g.dataset.type!==type});
   if(sel.dataset.appliedType!==type&&!sel.dataset.touched){const init=(sel.dataset.initial||'').trim();const match=[...sel.querySelectorAll('optgroup[data-type="'+type+'"] option')].find(o=>init!==''&&(o.value===init||o.textContent.trim()===init||o.textContent.trim().startsWith(init+' ')));sel.value=match?match.value:'';sel.dataset.appliedType=type;}sel.hidden=!(type==='FI'||type==='DSV');row.querySelector('[data-pclass-none]').hidden=!sel.hidden;masters[row.dataset.sourceIndex+'|'+key(val(row,'object'))]={value:sel.value,label:sel.value===''?'–':sel.selectedOptions[0].textContent};return}
  const span=row.querySelector('[data-inherit-pclass]');if(!span)return;
  const m=masters[row.dataset.sourceIndex+'|'+key(val(row,'object'))];
  if(m){row.querySelector('[data-field="provider_class"]').value=m.value;span.textContent=(type==='FI'||type==='DSV')?m.label:'–'}else span.textContent='–';
 });
 [...table.querySelectorAll('thead th')].forEach((th,i)=>{if(['Angeboten','Bereitstellungsart','Anderer RV / externer DL'].includes(th.textContent.trim()))table.querySelectorAll('tr').forEach(tr=>tr.children[i]?.classList.toggle('auto-hidden',!anyRv))});
};
const updateInherit=()=>{
 const masters={};
 rows.forEach(row=>{
  const src=row.dataset.sourceIndex||'0',obj=key(val(row,'object'));
  const holder=row.querySelector('[data-inherit="start"]');
  if(!holder){if(val(row,'service')===''&&val(row,'scope')==='Rolloutobjekt'){const id=val(row,'object_id');const old=id?state.objects[id]:null;masters[src+'|'+obj]={s:val(row,'start')||(old?old.s:''),e:val(row,'end')||(old?old.e:''),f:val(row,'functional')||(old?old.f:''),old}}return}
  const m=masters[src+'|'+obj];const id=val(row,'object_id');const old=m?m.old:(id?state.objects[id]:null);
  const s=m?m.s:(old?old.s:''),e=m?m.e:(old?old.e:''),f=m?m.f:(old?old.f:'');
  const set=(name,text,was)=>{const el=row.querySelector('[data-inherit="'+name+'"]');el.textContent=text||'–';el.className=text&&was!==undefined&&was!==text?'fw-semibold text-body':''};
  set('start',s,old?old.s:undefined);set('end',e,old?old.e:undefined);set('class',f,old?old.f:undefined);
 });
};
const summary=()=>{const rows=[...form.querySelectorAll('[data-import-row]')];const on=rows.filter(r=>val(r,'include')!=='');document.getElementById('import-row-summary').textContent=on.length+' von '+rows.length+' Zeilen werden übernommen · '+on.filter(r=>r.dataset.changed==='1').length+' mit Änderung'};
const rows=[...form.querySelectorAll('[data-import-row]')];
const table=form.querySelector('.import-review-table');
const refreshAll=()=>{rows.forEach(syncPanel);syncNewGroups();updateFeedback();filterServiceOptions();rows.forEach(refreshRow);updateInherit();summary()};
rows.forEach(row=>{row.addEventListener('input',refreshAll);row.addEventListener('change',refreshAll)});refreshAll();
form.querySelectorAll('[data-file-provider]').forEach(s=>s.addEventListener('change',refreshAll));
document.querySelectorAll('[data-bulk]').forEach(btn=>btn.addEventListener('click',()=>{
 rows.forEach(row=>{const inc=row.querySelector('[data-field="include"]');const warned=!!row.querySelector('.text-danger');
