    $serviceStmt=$db->prepare('SELECT s.* FROM project_services ps JOIN support_services s ON s.id=ps.support_service_id WHERE ps.project_id=? AND s.active=1 ORDER BY s.name COLLATE NOCASE');
    $usageStmt=$db->prepare('SELECT support_service_id FROM project_service_rollout_objects WHERE project_id=? AND rollout_object_id=?');
    $projectQuery=$onlyProjectId?'SELECT * FROM projects WHERE id='.(int)$onlyProjectId:'SELECT * FROM projects ORDER BY name';
