            $rows[]=[(string)$project['name'],'Rolloutobjekt',(string)$object['name'],format_date($object['start_date'],''),format_date($object['end_date'],''),(string)$object['functional_class'],(string)($object['fi_class_code']??$object['technical_class']),'','','',(string)$object['notes']];
            $masterExcelRow=count($rows);
            $usageStmt->execute([(int)$project['id'],(int)$object['id']]);$selectedIds=array_map('intval',array_column($usageStmt->fetchAll(),'support_service_id'));
            $selectedFunctional=[];$selectedTechnical=[];$selectedOutside=[];
            foreach($selectedIds as $serviceId){if(!isset($projectServices[$serviceId]))continue;$service=$projectServices[$serviceId];[$functional,$technical]=service_dimension_codes($service);$targets=(array)$service['provider_targets'];if(!empty($service['is_standard'])&&in_array('RV',$targets,true)&&array_intersect($functional,cumulative_functional_classes((string)$object['functional_class'])))$selectedFunctional[]=(string)$service['name'];elseif(!empty($service['is_standard'])&&array_intersect(['FI','DSV'],$targets)&&array_intersect($technical,cumulative_technical_classes((string)($object['fi_class_code']??$object['technical_class']))))$selectedTechnical[]=(string)$service['name'];else$selectedOutside[]=(string)$service['name'];}
            natcasesort($selectedFunctional);natcasesort($selectedTechnical);natcasesort($selectedOutside);$selectedFunctional=array_values($selectedFunctional);$selectedTechnical=array_values($selectedTechnical);$selectedOutside=array_values($selectedOutside);
            $slotCount=max(8,count($selectedFunctional),count($selectedTechnical),count($selectedOutside));
            for($slot=0;$slot<$slotCount;$slot++){$rows[]=['','Leistungsauswahl','','','','','',$selectedFunctional[$slot]??'',$selectedTechnical[$slot]??'',$selectedOutside[$slot]??'',''];$validationRows[count($rows)]=['master_row'=>$masterExcelRow];}
