    return ['rows'=>$rows,'legend'=>$legend,'lists'=>$lists,'validation_rows'=>$validationRows];
}

/** Phase 2: FI bzw. DSV wählen ihre geplanten Leistungen je Rolloutobjekt. */
function central_provider_template_workbook(PDO $db,array $provider): array {
    if(!in_array((string)$provider['type'],['FI','DSV'],true))throw new RuntimeException('Diese Vorlage ist nur für FI oder DSV vorgesehen.');
    sync_mandatory_services($db);
    $type=(string)$provider['type'];$levels=provider_class_levels($db,$type,true);if(!$levels)throw new RuntimeException('Für '.$type.' ist kein Klassenschema hinterlegt.');$dimension=$type==='DSV'?'dsv':'technical';
    $standards=enrich_support_services($db,$db->query('SELECT * FROM support_services WHERE is_standard=1 AND active=1 ORDER BY name COLLATE NOCASE')->fetchAll());
    $lists=[$type.'_EMPTY'=>[''],$type.'_CLASS'=>array_column($levels,'class_label')];$allowedCodes=[];
    foreach($levels as $index=>$level){$allowedCodes[]=(string)$level['class_code'];$items=[];foreach($standards as $service){$serviceCodes=[];foreach((array)$service['class_codes'] as $entry){[$entryDimension,$code]=array_pad(explode(':',(string)$entry,2),2,'');if($entryDimension===$dimension)$serviceCodes[]=$code;}if(in_array($type,(array)$service['provider_targets'],true)&&array_intersect($serviceCodes,$allowedCodes))$items[(int)$service['id']]=$service;}usort($items,static fn(array $a,array $b):int=>strnatcasecmp((string)$a['name'],(string)$b['name']));$lists[$type.'_L'.($index+1)]=array_values(array_map(static fn(array $service):string=>(string)$service['name'],$items));if(!$lists[$type.'_L'.($index+1)])$lists[$type.'_L'.($index+1)]=[''];}
    $headers=['Projekt','Datensatz','Rolloutobjekt','Rolloutbeginn','Rolloutende','Rolloutklasse '.$type,'Katalogleistung '.$type,'Unterstützungsleistung außerhalb des Katalogs'];
    if($type==='DSV')$headers[]='Als neue Katalogleistung vorschlagen';
    array_push($headers,'Termin / Zeitraum','Bemerkung','Ansprechpartner','Telefonnummer');
    $rows=[$headers];$validationRows=[];$classRows=[];$contactStmt=$db->prepare('SELECT contact_name,contact_phone FROM project_provider_contacts WHERE project_id=? AND provider_id=?');$objectStmt=$db->prepare('SELECT * FROM rollout_objects WHERE project_id=? ORDER BY start_date,name');$servicesStmt=$db->prepare('SELECT s.*,COALESCE(om.offered,m.offered,0) offered,COALESCE(om.schedule,m.schedule,\'\') schedule,COALESCE(om.note,m.note,\'\') note FROM project_service_rollout_objects u JOIN support_services s ON s.id=u.support_service_id JOIN support_service_provider_targets t ON t.support_service_id=s.id AND t.provider_type=? LEFT JOIN rollout_object_support_matrix om ON om.rollout_object_id=u.rollout_object_id AND om.support_service_id=s.id AND om.provider_id=? LEFT JOIN project_support_matrix m ON m.project_id=u.project_id AND m.support_service_id=s.id AND m.provider_id=? WHERE u.project_id=? AND u.rollout_object_id=? AND s.active=1 ORDER BY s.name COLLATE NOCASE');
    foreach($db->query('SELECT * FROM projects ORDER BY name')->fetchAll() as $project){
        $contactStmt->execute([(int)$project['id'],(int)$provider['id']]);$contact=$contactStmt->fetch()?:['contact_name'=>'','contact_phone'=>''];$objectStmt->execute([(int)$project['id']]);$objects=enrich_rollout_objects($db,$objectStmt->fetchAll());$firstObject=true;
        foreach($objects as $object){$classLabel=$type==='DSV'?(string)$object['dsv_class_label']:(string)$object['fi_class_label'];$master=[(string)$project['name'],'Rolloutobjekt',(string)$object['name'],format_date($object['start_date'],''),format_date($object['end_date'],''),$classLabel,'',''];if($type==='DSV')$master[]='';array_push($master,'','',$firstObject?(string)$contact['contact_name']:'',$firstObject?(string)$contact['contact_phone']:'');$rows[]=$master;$masterRow=count($rows);$classRows[]=$masterRow;$firstObject=false;
            $servicesStmt->execute([$type,(int)$provider['id'],(int)$provider['id'],(int)$project['id'],(int)$object['id']]);$selected=[];foreach(enrich_support_services($db,$servicesStmt->fetchAll()) as $service)if(service_applies_to_provider($service,$provider,$object))$selected[]=$service;$slotCount=max(8,count($selected));
            for($slot=0;$slot<$slotCount;$slot++){$service=$selected[$slot]??null;$catalog='';$outside='';$schedule='';$note='';if($service){if(!empty($service['is_standard']))$catalog=(string)$service['name'];else$outside=(string)$service['name'];$schedule=!empty($service['schedule_relevant'])?(string)$service['schedule']:'Nicht relevant';$note=(string)$service['note'];}$selection=[(string)$project['name'],'Leistungsauswahl','','','','',$catalog,$outside];if($type==='DSV')$selection[]='Nein';array_push($selection,$schedule,$note,'','');$rows[]=$selection;$validationRows[count($rows)]=['master_row'=>$masterRow];}
        }
    }
    if(count($rows)===1)throw new RuntimeException('Es sind noch keine Rolloutobjekte vorhanden.');
    return ['rows'=>$rows,'legend'=>export_legend($db,$type),'lists'=>$lists,'validation_rows'=>$validationRows,'class_rows'=>$classRows,'provider_type'=>$type];
}

function catalog_maintenance_workbook(PDO $db,string $providerType): array {
    if(!in_array($providerType,['RV','FI','DSV'],true))throw new RuntimeException('Ungültiger Katalogbereich.');
    if($providerType==='RV'){$dimension='functional';$levels=[['class_code'=>'A','class_label'=>'A'],['class_code'=>'B','class_label'=>'B'],['class_code'=>'C','class_label'=>'C'],['class_code'=>'D','class_label'=>'D']];}
    else{$dimension=$providerType==='FI'?'technical':'dsv';$levels=provider_class_levels($db,$providerType);}
    $headers=['Leistung-ID','Unterstützungsleistung','Beschreibung'];foreach($levels as $level)$headers[]='Klasse '.(string)$level['class_label'];array_push($headers,'Obligatorisch','Immer enthalten','Termin / Zeitraum relevant','Aktiv');
    $stmt=$db->prepare('SELECT s.* FROM support_services s JOIN support_service_provider_targets t ON t.support_service_id=s.id AND t.provider_type=? WHERE s.is_standard=1 ORDER BY s.name COLLATE NOCASE');$stmt->execute([$providerType]);$services=enrich_support_services($db,$stmt->fetchAll());$rows=[$headers];
    foreach($services as $service){$codes=[];foreach((array)$service['class_codes'] as $entry){[$entryDimension,$code]=array_pad(explode(':',(string)$entry,2),2,'');if($entryDimension===$dimension)$codes[]=$code;}$firstLevel=null;foreach($levels as $levelIndex=>$level){if(in_array((string)$level['class_code'],$codes,true)){$firstLevel=$levelIndex;break;}}$row=[(string)$service['id'],(string)$service['name'],(string)$service['description']];foreach($levels as $levelIndex=>$level)$row[]=$firstLevel!==null&&$levelIndex>=$firstLevel?'Ja':'Nein';array_push($row,!empty($service['mandatory_for_all'])?'Ja':'Nein',!empty($service['always_included'])?'Ja':'Nein',!empty($service['schedule_relevant'])?'Ja':'Nein',!empty($service['active'])?'Ja':'Nein');$rows[]=$row;}
    for($index=0;$index<20;$index++){$row=['','',''];foreach($levels as $_)$row[]='Nein';array_push($row,'Nein','Nein','Ja','Ja');$rows[]=$row;}
    $classStart=3;$classColumns=range($classStart,$classStart+count($levels)-1);$flagColumns=[$classStart+count($levels),$classStart+count($levels)+1,$classStart+count($levels)+2,$classStart+count($levels)+3];
    return ['rows'=>$rows,'legend'=>export_legend($db,$providerType),'class_columns'=>$classColumns,'flag_columns'=>$flagColumns,'provider_type'=>$providerType,'dimension'=>$dimension,'levels'=>$levels];
}

function download_catalog_maintenance(PDO $db,string $providerType): never {
    $labels=['RV'=>'Regionalverbaende','FI'=>'FI','DSV'=>'DSV'];$workbook=catalog_maintenance_workbook($db,$providerType);Xlsx::downloadBinary(Xlsx::catalogMaintenanceBinary($workbook),'Leistungskatalog-'.$labels[$providerType].'-'.date('d.m.Y').'.xlsx');
}

function import_catalog_maintenance(PDO $db,string $providerType,array $rows,bool $manageTransaction=true): int {
