    $yes=static fn(string $value):bool=>in_array(mb_strtolower(trim($value)),['ja','1','x','true'],true);$levels=(array)$definition['levels'];$dimension=(string)$definition['dimension'];$seen=[];$count=0;if($manageTransaction)$db->beginTransaction();
    $find=$db->prepare('SELECT id,is_standard FROM support_services WHERE id=?');$update=$db->prepare('UPDATE support_services SET name=?,description=?,mandatory_for_all=?,always_included=COALESCE(?,always_included),schedule_relevant=?,active=? WHERE id=? AND is_standard=1');$insert=$db->prepare('INSERT INTO support_services(name,description,is_standard,project_id,mandatory_for_all,always_included,schedule_relevant,active,sort_order) VALUES(?,?,1,NULL,?,?,?,?,0)');$target=$db->prepare('INSERT OR IGNORE INTO support_service_provider_targets(support_service_id,provider_type) VALUES(?,?)');$deleteClasses=$db->prepare('DELETE FROM support_service_classes WHERE support_service_id=? AND dimension=?');$insertClass=$db->prepare('INSERT INTO support_service_classes(support_service_id,dimension,class_code) VALUES(?,?,?)');
    foreach(array_slice($rows,1) as $rowNumber=>$row){$get=static fn(string $header):string=>trim((string)($row[$map[$header]]??''));$id=(int)$get('Leistung-ID');$name=$get('Unterstützungsleistung');if($id===0&&$name==='')continue;if($name==='')throw new RuntimeException('Zeile '.($rowNumber+2).': Die Unterstützungsleistung darf nicht leer sein.');if($id&&isset($seen[$id]))throw new RuntimeException('Zeile '.($rowNumber+2).': Die Leistung-ID '.$id.' kommt mehrfach vor.');$selected=[];foreach($levels as $level){$header='Klasse '.(string)$level['class_label'];if($yes($get($header))){$selected[]=(string)$level['class_code'];break;}}if(!$selected)throw new RuntimeException('Zeile '.($rowNumber+2).': Bitte mindestens eine Klasse mit „Ja“ kennzeichnen.');$mandatory=$yes($get('Obligatorisch'))?1:0;$always=isset($map['Immer enthalten'])?($yes($get('Immer enthalten'))?1:0):null;$schedule=$yes($get('Termin / Zeitraum relevant'))?1:0;$active=$yes($get('Aktiv'))?1:0;
        if($id){$find->execute([$id]);$existing=$find->fetch();if(!$existing||empty($existing['is_standard']))throw new RuntimeException('Zeile '.($rowNumber+2).': Die Standardleistung mit ID '.$id.' wurde nicht gefunden.');$update->execute([$name,$get('Beschreibung'),$mandatory,$always,$schedule,$active,$id]);$seen[$id]=true;}else{$insert->execute([$name,$get('Beschreibung'),$mandatory,$always??0,$schedule,$active]);$id=(int)$db->lastInsertId();}
        $target->execute([$id,$providerType]);$deleteClasses->execute([$id,$dimension]);foreach($selected as $code)$insertClass->execute([$id,$dimension,$code]);if(!$schedule)$db->prepare("UPDATE project_support_matrix SET schedule='' WHERE support_service_id=?")->execute([$id]);$count++;
    }
    if(!$count)throw new RuntimeException('Die Katalogdatei enthält keine ausgefüllte Leistung.');prune_invalid_service_rollout_usage($db);sync_mandatory_services($db);if($manageTransaction)$db->commit();return $count;
}

function import_state_snapshot(PDO $db): array {
    $state=[];$add=static function(string $key,string $category,string $subject,array $fields)use(&$state):void{$state[$key]=['category'=>$category,'subject'=>$subject,'fields'=>array_map(static fn($value):string=>(string)$value,$fields)];};
    foreach($db->query('SELECT * FROM providers ORDER BY id')->fetchAll() as $row)$add('provider:'.$row['id'],'Leistungserbringer',(string)$row['name'],['Typ'=>$row['type'],'Bezeichnung'=>$row['name'],'Aktiv'=>$row['active']?'Ja':'Nein']);
    foreach($db->query('SELECT * FROM provider_class_levels ORDER BY provider_type,sort_order')->fetchAll() as $row)$add('provider-level:'.$row['provider_type'].':'.$row['class_code'],'Klassenschema',$row['provider_type'].' / '.$row['class_label'],['Code'=>$row['class_code'],'Bezeichnung'=>$row['class_label'],'Reihenfolge'=>$row['sort_order']]);
    foreach($db->query('SELECT * FROM projects ORDER BY id')->fetchAll() as $row)$add('project:'.$row['id'],'Projekt',(string)$row['name'],['Projektname'=>$row['name'],'Projektleitung'=>$row['project_lead'],'TPL Rollout'=>$row['rollout_lead'],'Beschreibung'=>$row['description']]);
    foreach($db->query('SELECT r.*,p.name project_name FROM rollout_objects r JOIN projects p ON p.id=r.project_id ORDER BY r.id')->fetchAll() as $row)$add('object:'.$row['id'],'Rolloutobjekt',$row['project_name'].' / '.$row['name'],['Bezeichnung'=>$row['name'],'Beginn'=>format_date($row['start_date'],''),'Ende'=>format_date($row['end_date'],''),'Klasse Bankfachlich'=>$row['functional_class']??'','Klasse FI'=>$row['technical_class']??'','Bemerkung'=>$row['notes']]);
    foreach($db->query("SELECT c.*,r.name object_name,p.name project_name,l.class_label FROM rollout_object_provider_classes c JOIN rollout_objects r ON r.id=c.rollout_object_id JOIN projects p ON p.id=r.project_id LEFT JOIN provider_class_levels l ON l.provider_type=c.provider_type AND l.class_code=c.class_code ORDER BY c.rollout_object_id,c.provider_type")->fetchAll() as $row)$add('object-class:'.$row['rollout_object_id'].':'.$row['provider_type'],'Rolloutklasse',$row['project_name'].' / '.$row['object_name'].' / '.$row['provider_type'],['Klasse'=>$row['class_label']?:$row['class_code']]);
    foreach($db->query('SELECT s.*,p.name project_name FROM support_services s LEFT JOIN projects p ON p.id=s.project_id ORDER BY s.id')->fetchAll() as $row)$add('service:'.$row['id'],$row['is_standard']?'Katalogleistung':'Zusätzliche Leistung',(string)$row['name'],['Bezeichnung'=>$row['name'],'Beschreibung'=>$row['description'],'Projekt'=>$row['project_name']??'zentral','Obligatorisch'=>$row['mandatory_for_all']?'Ja':'Nein','Immer enthalten'=>!empty($row['always_included'])?'Ja':'Nein','Termin/Zeitraum relevant'=>$row['schedule_relevant']?'Ja':'Nein','Aktiv'=>$row['active']?'Ja':'Nein']);
    foreach($db->query('SELECT c.*,s.name service_name FROM support_service_classes c JOIN support_services s ON s.id=c.support_service_id ORDER BY c.support_service_id,c.dimension,c.class_code')->fetchAll() as $row)$add('service-class:'.$row['support_service_id'].':'.$row['dimension'].':'.$row['class_code'],'Leistungsklasse',(string)$row['service_name'],['Bereich'=>match($row['dimension']){'functional'=>'Bankfachlich','technical'=>'FI',default=>'DSV'},'Klasse'=>$row['class_code']]);
    foreach($db->query('SELECT t.*,s.name service_name FROM support_service_provider_targets t JOIN support_services s ON s.id=t.support_service_id ORDER BY t.support_service_id,t.provider_type')->fetchAll() as $row)$add('service-target:'.$row['support_service_id'].':'.$row['provider_type'],'Zuständigkeit',(string)$row['service_name'],['Leistungserbringer'=>$row['provider_type']]);
    foreach($db->query('SELECT ps.*,p.name project_name,s.name service_name FROM project_services ps JOIN projects p ON p.id=ps.project_id JOIN support_services s ON s.id=ps.support_service_id ORDER BY ps.project_id,ps.support_service_id')->fetchAll() as $row)$add('project-service:'.$row['project_id'].':'.$row['support_service_id'],'Projektleistung',$row['project_name'].' / '.$row['service_name'],['Zuordnung'=>'vorhanden']);
    foreach($db->query('SELECT u.*,p.name project_name,s.name service_name,r.name object_name FROM project_service_rollout_objects u JOIN projects p ON p.id=u.project_id JOIN support_services s ON s.id=u.support_service_id JOIN rollout_objects r ON r.id=u.rollout_object_id ORDER BY u.project_id,u.support_service_id,u.rollout_object_id')->fetchAll() as $row)$add('usage:'.$row['project_id'].':'.$row['support_service_id'].':'.$row['rollout_object_id'],'Nutzung am Rolloutobjekt',$row['project_name'].' / '.$row['object_name'].' / '.$row['service_name'],['Nutzung'=>'vorgesehen']);
    foreach($db->query('SELECT c.*,p.name project_name,v.name provider_name FROM project_provider_contacts c JOIN projects p ON p.id=c.project_id JOIN providers v ON v.id=c.provider_id ORDER BY c.project_id,c.provider_id')->fetchAll() as $row)$add('contact:'.$row['project_id'].':'.$row['provider_id'],'Ansprechpartner',$row['project_name'].' / '.$row['provider_name'],['Name'=>$row['contact_name'],'Telefon'=>$row['contact_phone']]);
    foreach($db->query('SELECT m.*,p.name project_name,s.name service_name,v.name provider_name FROM project_support_matrix m JOIN projects p ON p.id=m.project_id JOIN support_services s ON s.id=m.support_service_id JOIN providers v ON v.id=m.provider_id ORDER BY m.project_id,m.support_service_id,m.provider_id')->fetchAll() as $row)$add('matrix:'.$row['project_id'].':'.$row['support_service_id'].':'.$row['provider_id'],'Projektangabe',$row['project_name'].' / '.$row['service_name'].' / '.$row['provider_name'],['Geplant'=>$row['offered']?'Ja':'Nein','Bereitstellungsart'=>delivery_mode_label((string)$row['delivery_mode']),'Partner/Dienstleister'=>$row['delivery_partner'],'Termin/Zeitraum'=>$row['schedule'],'Bemerkung'=>$row['note']]);
    foreach($db->query('SELECT m.*,p.name project_name,r.name object_name,s.name service_name,v.name provider_name FROM rollout_object_support_matrix m JOIN projects p ON p.id=m.project_id JOIN rollout_objects r ON r.id=m.rollout_object_id JOIN support_services s ON s.id=m.support_service_id JOIN providers v ON v.id=m.provider_id ORDER BY m.rollout_object_id,m.support_service_id,m.provider_id')->fetchAll() as $row)$add('object-matrix:'.$row['rollout_object_id'].':'.$row['support_service_id'].':'.$row['provider_id'],'Angabe am Rolloutobjekt',$row['project_name'].' / '.$row['object_name'].' / '.$row['service_name'].' / '.$row['provider_name'],['Geplant'=>$row['offered']?'Ja':'Nein','Termin/Zeitraum'=>$row['schedule'],'Bemerkung'=>$row['note']]);
    foreach($db->query('SELECT s.*,p.name project_name,r.name object_name,v.name provider_name FROM catalog_service_suggestions s JOIN projects p ON p.id=s.project_id JOIN rollout_objects r ON r.id=s.rollout_object_id JOIN providers v ON v.id=s.provider_id ORDER BY s.id')->fetchAll() as $row)$add('suggestion:'.$row['id'],'Katalogvorschlag',$row['project_name'].' / '.$row['object_name'].' / '.$row['proposed_name'],['Vorgeschlagen von'=>$row['provider_name'],'Klasse'=>$row['class_code'],'Status'=>$row['status'],'Termin/Zeitraum'=>$row['schedule'],'Bemerkung'=>$row['note']]);
    ksort($state);return $state;
}

function import_state_hash(PDO $db): string {return hash('sha256',serialize(import_state_snapshot($db)));}

function compare_import_states(array $before,array $after): array {
    $changes=[];$keys=array_values(array_unique(array_merge(array_keys($before),array_keys($after))));sort($keys);
    foreach($keys as $key){$old=$before[$key]??null;$new=$after[$key]??null;if($old===null){$changes[]=['type'=>'new','category'=>$new['category'],'subject'=>$new['subject'],'field'=>'Neuer Datensatz','old'=>'','new'=>implode(' · ',array_filter(array_map(static fn($name,$value):string=>$value!==''?$name.': '.$value:'',array_keys($new['fields']),$new['fields'])))];continue;}if($new===null){$changes[]=['type'=>'delete','category'=>$old['category'],'subject'=>$old['subject'],'field'=>'Datensatz oder Zuordnung','old'=>implode(' · ',array_filter(array_map(static fn($name,$value):string=>$value!==''?$name.': '.$value:'',array_keys($old['fields']),$old['fields']))),'new'=>''];continue;}$fields=array_values(array_unique(array_merge(array_keys($old['fields']),array_keys($new['fields']))));foreach($fields as $field){$oldValue=(string)($old['fields'][$field]??'');$newValue=(string)($new['fields'][$field]??'');if($oldValue!==$newValue)$changes[]=['type'=>$newValue===''?'clear':'change','category'=>$new['category'],'subject'=>$new['subject'],'field'=>$field,'old'=>$oldValue,'new'=>$newValue];}}
    return $changes;
}

function simulate_import_changes(PDO $db,callable $runner): array {
    $before=import_state_snapshot($db);$stateHash=hash('sha256',serialize($before));$db->beginTransaction();try{$result=$runner();$after=import_state_snapshot($db);$db->rollBack();}catch(Throwable $error){if($db->inTransaction())$db->rollBack();throw $error;}return ['changes'=>compare_import_states($before,$after),'result'=>$result,'state_hash'=>$stateHash];
}

