function provider_template(PDO $db,int $providerId): array {
    $stmt=$db->prepare('SELECT * FROM providers WHERE id=? AND active=1');$stmt->execute([$providerId]);$provider=$stmt->fetch();if(!$provider)throw new RuntimeException('Leistungserbringer nicht gefunden.');return [$provider,provider_template_rows($db,$provider)];
