function safe_template_filename(string $name): string {
    return trim((string)preg_replace('/[^a-zA-Z0-9_-]+/','-',str_replace(['ä','ö','ü','Ä','Ö','Ü','ß'],['ae','oe','ue','Ae','Oe','Ue','ss'],$name)),'-');
}

function download_tpl_template(PDO $db,int $projectId=0,bool $includeProviderData=false): never {
    $projectName='Gesamt';if($projectId){$stmt=$db->prepare('SELECT name FROM projects WHERE id=?');$stmt->execute([$projectId]);$projectName=(string)$stmt->fetchColumn();if($projectName==='')throw new RuntimeException('Projekt nicht gefunden.');}$workbook=tpl_template_workbook($db,$projectId,$includeProviderData);Xlsx::downloadBinary(Xlsx::tplPlanningBinary($workbook),'TPL-Rollout-Planung-'.safe_template_filename($projectName).'-'.date('d.m.Y').'.xlsx');
}

function download_tpl_template_archive(PDO $db,bool $includeProviderData=false): never {
    $files=[];foreach($db->query('SELECT id,name FROM projects ORDER BY name')->fetchAll() as $project)$files['TPL-Rollout-Planung-'.safe_template_filename((string)$project['name']).'.xlsx']=Xlsx::tplPlanningBinary(tpl_template_workbook($db,(int)$project['id'],$includeProviderData));if(!$files)throw new RuntimeException('Es sind noch keine Projekte vorhanden.');Xlsx::downloadArchive($files,'TPL-Rollout-Planungen-'.date('d.m.Y').'.zip');
