function download_provider_template(PDO $db,int $providerId): never {
    [$provider,$rows]=provider_template($db,$providerId);if(in_array((string)$provider['type'],['FI','DSV'],true)){Xlsx::downloadBinary(Xlsx::centralProviderPlanningBinary(central_provider_template_workbook($db,$provider)),'Rollout-Unterstuetzung-'.safe_template_filename((string)$provider['name']).'-'.date('d.m.Y').'.xlsx');}Xlsx::download($rows,'Rollout-Unterstuetzung-'.safe_template_filename((string)$provider['name']).'-'.date('d.m.Y').'.xlsx',(string)$provider['name'],['layout'=>'provider-feedback','provider_type'=>$provider['type'],'legend'=>export_legend($db,(string)$provider['type'])]);
