function import_service_catalog(PDO $db): array {
    return $db->query("SELECT s.id,s.name,s.is_standard,s.project_id,p.name project_name FROM support_services s LEFT JOIN projects p ON p.id=s.project_id WHERE s.active=1 ORDER BY s.is_standard DESC,s.name COLLATE NOCASE")->fetchAll();
