            $insertClass=$db->prepare('INSERT INTO support_service_classes(support_service_id,dimension,class_code) VALUES(?,?,?)');if($serviceFunctional)$insertClass->execute([$serviceId,'functional',$serviceFunctional]);if($serviceTechnical)$insertClass->execute([$serviceId,'technical',$serviceTechnical]);if($serviceDsv)$insertClass->execute([$serviceId,'dsv',$serviceDsv]);
            $targetTypes=array_values(array_intersect(array_map('trim',explode(',',$value($row,'new_provider_targets'))),['RV','FI','DSV']));$sourceProvider=$value($row,'provider');if(!$targetTypes&&$sourceProvider!==''){$stmt=$db->prepare('SELECT type FROM providers WHERE name=?');$stmt->execute([$sourceProvider]);$sourceType=(string)$stmt->fetchColumn();if(in_array($sourceType,['RV','FI','DSV'],true))$targetTypes[]=$sourceType;}if(!$targetTypes){if($serviceFunctional)$targetTypes[]='RV';if($serviceTechnical)$targetTypes[]='FI';if($serviceDsv)$targetTypes[]='DSV';}$insertTarget=$db->prepare('INSERT INTO support_service_provider_targets(support_service_id,provider_type) VALUES(?,?)');foreach(array_unique($targetTypes) as $targetType)$insertTarget->execute([$serviceId,$targetType]);
            $stmt=$db->prepare('SELECT * FROM support_services WHERE id=?');$stmt->execute([$serviceId]);$serviceRow=$stmt->fetch();
        }
