        }

        if($service!==''&&in_array(mb_strtolower($value($row,'catalog_suggestion')),['ja','1','x','true'],true)){$stmt=$db->prepare("SELECT COUNT(*) FROM catalog_service_suggestions WHERE provider_id=? AND rollout_object_id=? AND proposed_name=? AND status='pending'");$stmt->execute([$providerId,$objectId,$service]);if(!(int)$stmt->fetchColumn()){$stmt=$db->prepare('INSERT INTO catalog_service_suggestions(provider_type,provider_id,project_id,rollout_object_id,proposed_name,class_code,offered,schedule,note) VALUES(?,?,?,?,?,?,?,?,?)');$stmt->execute([$providerType,$providerId,$projectId,$objectId,$service,$providerClassCode,$value($row,'offered')==='Ja'?1:0,$value($row,'schedule'),$value($row,'note')]);}continue;}
        $meta=null;if($serviceId){$meta=enrich_support_services($db,[['id'=>$serviceId]+($serviceRow?:[])])[0];if($providerId){if($objectId){$stmt=$db->prepare('SELECT * FROM rollout_objects WHERE id=?');$stmt->execute([$objectId]);$objectRow=$stmt->fetch();$classObject=$objectRow?enrich_rollout_objects($db,[$objectRow])[0]:null;}else{$classScope=project_rollout_class_scope($db,$projectId);$classObject=['functional_class'=>$classScope['functional']?$classScope['functional'][count($classScope['functional'])-1]:null,'technical_class'=>$classScope['technical']?$classScope['technical'][count($classScope['technical'])-1]:null,'dsv_class_code'=>$classScope['dsv']?$classScope['dsv'][count($classScope['dsv'])-1]:null];}if(!$classObject||!service_applies_to_provider($meta,['id'=>$providerId,'type'=>$providerType],$classObject))throw new RuntimeException('Die Projektleistung „'.$service.'“ passt nicht zur Klasse des gewählten Rolloutobjekts oder zum Leistungserbringer.');}}
