        $contactName=$value($row,'contact_name');$contactPhone=$value($row,'contact_phone');if($providerId&&($contactName!==''||$contactPhone!=='')){$stmt=$db->prepare('INSERT INTO project_provider_contacts(project_id,provider_id,contact_name,contact_phone) VALUES(?,?,?,?) ON CONFLICT(project_id,provider_id) DO UPDATE SET contact_name=excluded.contact_name,contact_phone=excluded.contact_phone,updated_at=CURRENT_TIMESTAMP');$stmt->execute([$projectId,$providerId,$contactName,$contactPhone]);}
        $offered=in_array(mb_strtolower($value($row,'offered')),['ja','1','x','true'],true)?1:0;$deliveryMode=normalize_delivery_mode($value($row,'delivery_mode'));$deliveryPartner=trim($value($row,'delivery_partner'));$mandatory=$meta&&$providerId?service_is_mandatory_for_provider($meta,['id'=>$providerId,'type'=>$providerType]):false;$requiresDelivery=!empty($meta['requires_delivery_source'])&&!$mandatory;if($providerType==='RV'&&$requiresDelivery){if($deliveryMode===''&&$offered)$deliveryMode='self';if(in_array($deliveryMode,['other_rv','external'],true)&&$deliveryPartner==='')throw new RuntimeException('Für die Unterstützungsleistung „'.$service.'“ fehlt der andere Regionalverband beziehungsweise der externe Dienstleister.');if($deliveryMode==='other_rv'){$stmt=$db->prepare("SELECT id FROM providers WHERE type='RV' AND active=1 AND name=?");$stmt->execute([$deliveryPartner]);$partnerId=(int)$stmt->fetchColumn();if(!$partnerId||$partnerId===$providerId)throw new RuntimeException('Für die Unterstützungsleistung „'.$service.'“ muss ein anderer aktiver Regionalverband angegeben werden.');}if(!in_array($deliveryMode,['other_rv','external'],true))$deliveryPartner='';if($deliveryMode!=='')$offered=in_array($deliveryMode,['self','other_rv','external'],true)?1:0;}else{$deliveryMode='';$deliveryPartner='';}if($mandatory)$offered=1;$schedule=$meta&&!empty($meta['schedule_relevant'])?$value($row,'schedule'):'';
        if($serviceId&&$objectId){$db->prepare('INSERT OR IGNORE INTO project_service_rollout_objects(project_id,support_service_id,rollout_object_id) VALUES(?,?,?)')->execute([$projectId,$serviceId,$objectId]);$namedServices[$objectId][$serviceId]=true;}
        if($serviceId&&$masterRowsOnly&&isset($map['used_objects'])&&!$objectId){$usageKey=$projectId.':'.$serviceId;if(!isset($clearedUsage[$usageKey])){$db->prepare('DELETE FROM project_service_rollout_objects WHERE project_id=? AND support_service_id=?')->execute([$projectId,$serviceId]);$clearedUsage[$usageKey]=true;}$mappingInsert=$db->prepare('INSERT OR IGNORE INTO project_service_rollout_objects(project_id,support_service_id,rollout_object_id) VALUES(?,?,?)');foreach(split_import_services($value($row,'used_objects')) as $objectName){$stmt=$db->prepare('SELECT * FROM rollout_objects WHERE project_id=? AND name=?');$stmt->execute([$projectId,$objectName]);$mappedObject=$stmt->fetch();if(!$mappedObject)throw new RuntimeException('Das bei „'.$service.'“ genannte Rolloutobjekt „'.$objectName.'“ gehört nicht zum Projekt.');$mappedObject=enrich_rollout_objects($db,[$mappedObject])[0];if($meta&&!service_applies_to_rollout_object($meta,$mappedObject))throw new RuntimeException('Die Projektleistung „'.$service.'“ passt aufgrund ihrer Klassen nicht zum Rolloutobjekt „'.$objectName.'“.');$mappingInsert->execute([$projectId,$serviceId,(int)$mappedObject['id']]);}}
        if($serviceId&&$providerId){if($objectId&&in_array($providerType,['FI','DSV'],true)){$stmt=$db->prepare('INSERT INTO rollout_object_support_matrix(rollout_object_id,project_id,support_service_id,provider_id,offered,schedule,note) VALUES(?,?,?,?,?,?,?) ON CONFLICT(rollout_object_id,support_service_id,provider_id) DO UPDATE SET offered=excluded.offered,automatic=0,schedule=excluded.schedule,note=excluded.note,updated_at=CURRENT_TIMESTAMP');$stmt->execute([$objectId,$projectId,$serviceId,$providerId,$offered,$schedule,$value($row,'note')]);}$stmt=$db->prepare('INSERT INTO project_support_matrix(project_id,support_service_id,provider_id,offered,delivery_mode,delivery_partner,schedule,note) VALUES(?,?,?,?,?,?,?,?) ON CONFLICT(project_id,support_service_id,provider_id) DO UPDATE SET offered=excluded.offered,automatic=0,delivery_mode=excluded.delivery_mode,delivery_partner=excluded.delivery_partner,schedule=excluded.schedule,note=excluded.note,updated_at=CURRENT_TIMESTAMP');$stmt->execute([$projectId,$serviceId,$providerId,$offered,$deliveryMode,$deliveryPartner,$schedule,$value($row,'note')]);}
    }
    if($replace!==null&&$masterRowsOnly)$counts['removed']=remove_unnamed_object_services($db,$touchedObjects,$namedServices,(array)($replace['keep']??[]),!empty($replace['technical']),!empty($replace['outside']));
    sync_mandatory_services($db);if($manageTransaction)$db->commit();return $counts;
}

/** Leistungen mit „Immer enthalten“ lassen sich weder streichen noch über „Datei ist maßgeblich“ entfernen. Obligatorisch betrifft nur die Abfrage bei den Leistungserbringern. */
function service_removal_protected(array $service): bool {
    return !empty($service['always_included']);
}

/** Entfernt die Nutzung einer Leistung an einem Rolloutobjekt; ohne weitere Nutzung im Projekt entfällt auch die Projektleistung samt Angaben der Leistungserbringer. */
function remove_object_service(PDO $db,int $projectId,int $serviceId,int $objectId): bool {
    $stmt=$db->prepare('DELETE FROM project_service_rollout_objects WHERE project_id=? AND support_service_id=? AND rollout_object_id=?');$stmt->execute([$projectId,$serviceId,$objectId]);if(!$stmt->rowCount())return false;
    $stmt=$db->prepare('SELECT COUNT(*) FROM project_service_rollout_objects WHERE project_id=? AND support_service_id=?');$stmt->execute([$projectId,$serviceId]);if(!(int)$stmt->fetchColumn())$db->prepare('DELETE FROM project_services WHERE project_id=? AND support_service_id=?')->execute([$projectId,$serviceId]);
    return true;
}

/** Modus „Datei ist maßgeblich“: entfernt am Rolloutobjekt Leistungen, die die TPL-Datei nicht mehr nennt. Leistungen mit „Immer enthalten“ bleiben immer erhalten. */
function import_replace_keep(array $reviewRows): array {
    $keep=[];foreach($reviewRows as $row){$objectId=(int)($row['object_id']??0);$serviceId=$row['service_id']??'';if($objectId&&is_numeric($serviceId)&&(int)$serviceId>0)$keep[$objectId][(int)$serviceId]=true;}return $keep;
}

function remove_unnamed_object_services(PDO $db,array $touchedObjects,array $namedServices,array $keep,bool $technicalInFile,bool $outsideInFile): int {
    $removed=0;$usageStmt=$db->prepare('SELECT support_service_id FROM project_service_rollout_objects WHERE project_id=? AND rollout_object_id=?');$serviceStmt=$db->prepare('SELECT * FROM support_services WHERE id=?');$objectStmt=$db->prepare('SELECT * FROM rollout_objects WHERE id=?');
    foreach($touchedObjects as $objectId=>$projectId){
        $objectStmt->execute([$objectId]);$objectRow=$objectStmt->fetch();if(!$objectRow)continue;$object=enrich_rollout_objects($db,[$objectRow])[0];
        $usageStmt->execute([$projectId,$objectId]);
        foreach(array_map('intval',array_column($usageStmt->fetchAll(),'support_service_id')) as $serviceId){
            if(isset($namedServices[$objectId][$serviceId])||isset($keep[$objectId][$serviceId]))continue;
            $serviceStmt->execute([$serviceId]);$serviceRow=$serviceStmt->fetch();if(!$serviceRow)continue;$service=enrich_support_services($db,[$serviceRow])[0];
            if(service_removal_protected($service))continue;
            $targets=(array)$service['provider_targets'];[$functional,$technical]=service_dimension_codes($service);
            if(empty($service['is_standard']))$domain='outside';
            elseif(!in_array('RV',$targets,true))$domain='technical';
            elseif(array_intersect($functional,cumulative_functional_classes($object['functional_class']??null)))$domain='functional';
            else$domain='outside';
            if($domain==='technical'&&!$technicalInFile)continue;if($domain==='outside'&&!$outsideInFile)continue;
            if(remove_object_service($db,$projectId,$serviceId,$objectId))$removed++;
        }
    }
    return $removed;
}

function parse_import_date(string $value): ?string {if($value==='')return null;if(is_numeric($value)&&$value>20000){$date=new DateTime('1899-12-30');$date->modify('+'.(int)$value.' days');return $date->format('Y-m-d');}return date_to_iso($value);}
